add_action('wp_footer', function() {
    if (is_singular('post')) {
        ?>
        <div id="bk-img-modal" class="bk-modal">
            <span class="bk-modal-close">&times;</span>
            <div id="bk-loader"></div> 
            <div class="bk-modal-flex">
                <img class="bk-modal-content" id="bk-expanded-img">
                <div id="bk-modal-caption"></div>
            </div>
        </div>

        <style>
        /* 1. Modal Overlay - Transparent Light Black + Blur */
        .bk-modal {
            display: none; 
            position: fixed; 
            z-index: 999999; 
            left: 0; top: 0; 
            width: 100%; height: 100%;
            background-color: rgba(0, 0, 0, 0.5); /* Lighter black */
            backdrop-filter: blur(40px);           /* Premium Transparent Blur */
            -webkit-backdrop-filter: blur(40px);
            transition: opacity 0.3s ease;
        }

        .bk-modal-flex { display: flex; flex-direction: column; justify-content: center; align-items: center; width: 100%; height: 100%; }

        /* 2. Zoom-In Animation */
        .bk-modal-content {
            max-width: 90%; max-height: 85vh; border-radius: 10px;
            display: none; 
            box-shadow: 0 15px 50px rgba(0,0,0,0.3);
            animation: bkZoomIn 0.4s cubic-bezier(0.165, 0.84, 0.44, 1) forwards;
        }

        /* 3. Zoom-Out Animation (When closing) */
        .bk-modal.bk-closing .bk-modal-content {
            animation: bkZoomOut 0.3s cubic-bezier(0.165, 0.84, 0.44, 1) forwards;
        }

        @keyframes bkZoomIn {
            from { transform: scale(0.9); opacity: 0; }
            to { transform: scale(1); opacity: 1; }
        }

        @keyframes bkZoomOut {
            from { transform: scale(1); opacity: 1; }
            to { transform: scale(0.9); opacity: 0; }
        }

        /* 4. Controls & Loader */
        #bk-loader {
            border: 3px solid #f3f3f3; border-top: 3px solid #3b82f6;
            border-radius: 50%; width: 30px; height: 30px;
            animation: bk-spin 1s linear infinite;
            position: absolute; top: 50%; left: 50%; margin: -15px 0 0 -15px; display: none;
        }
        @keyframes bk-spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }

        .bk-modal-close { 
            position: absolute; top: 20px; right: 30px; 
            color: #fff; font-size: 40px; font-weight: 300; 
            cursor: pointer; line-height: 1; z-index: 1000001;
        }
        #bk-modal-caption { color: #fff; padding: 15px; font-size: 14px; text-align: center; font-weight: 500; text-shadow: 0 2px 4px rgba(0,0,0,0.3); }

        .post-section-box img, .featured-image img { cursor: zoom-in; }
        </style>

        <script>
        document.addEventListener('DOMContentLoaded', function() {
            const modal = document.getElementById("bk-img-modal");
            const modalImg = document.getElementById("bk-expanded-img");
            const loader = document.getElementById("bk-loader");
            const images = document.querySelectorAll('.post-section-box img, .featured-image img');

            images.forEach(img => {
                img.onclick = function() {
                    modal.classList.remove("bk-closing");
                    modal.style.display = "block";
                    modal.style.opacity = "1";
                    loader.style.display = "block";
                    modalImg.style.display = "none";

                    let fullRes = this.src;
                    if (this.srcset) {
                        const sources = this.srcset.split(',').map(s => s.trim().split(' '));
                        fullRes = sources.sort((a, b) => parseInt(b[1]) - parseInt(a[1]))[0][0];
                    }

                    modalImg.src = fullRes;
                    modalImg.onload = function() {
                        loader.style.display = "none";
                        modalImg.style.display = "block";
                    };
                    document.body.style.overflow = "hidden";
                }
            });

            function closeModal() {
                modal.classList.add("bk-closing");
                modal.style.opacity = "0"; // Smooth fade out

                // Wait for animation (300ms) then hide
                setTimeout(() => {
                    modal.style.display = "none";
                    document.body.style.overflow = "auto";
                    modalImg.src = "";
                }, 300);
            }

            document.querySelector(".bk-modal-close").onclick = closeModal;
            modal.onclick = function(e) { if(e.target !== modalImg) closeModal(); }
            document.onkeydown = function(e) { if(e.key === "Escape") closeModal(); }
        });
        </script>
        <?php
    }
});
